#!/usr/bin/env node
/**
 * Keeps docs/feature-status.md honest.
 *
 *   node scripts/check-feature-status.mjs          # check (CI)
 *   node scripts/check-feature-status.mjs --write  # regenerate docs/feature-status.md
 *
 * Source of truth: frontend/lib/capabilities.ts. Features whose mode is "mock" must
 * never be listed as Available; the generated file is compared byte-for-byte so
 * hand edits that advertise a mock feature as available fail the check.
 */
import { readFileSync, writeFileSync, existsSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const capabilitiesPath = join(root, "frontend/lib/capabilities.ts");
const statusPath = join(root, "docs/feature-status.md");

const LABELS = {
  chat: "Agent chat",
  tasks: "Tasks",
  activity: "Activity and audit",
  telegram: "Telegram channel",
  google: "Google Workspace (Gmail, Calendar, Drive, Docs, Sheets)",
  memory: "Memory",
  automations: "Automations and scheduler (Routines)",
  goals: "Goals and plans",
  inbox: "Suggestions and unified Inbox",
  agent_control: "Agent control (pause / autonomy)",
  calendar: "Calendar screen",
  mail: "Mail screen",
  notes_diary: "Notes and diary",
  files: "Files and images",
  learning: "Learning (words and review)",
  reading: "Reading plans and log",
  profile_account: "Profile, photo, password and notifications",
  task_outcomes: "Task achievements (target, outcome, score)",
  days: "Day view, streak, carry-over",
  drive_backup: "Google Drive backup (organized Compass folder, asks first)",
  calendar_sync: "Google Calendar sync for tasks",
  daily_wrapup: "Evening wrap-up routine",
  habits: "Habits, check-ins and streaks (recurrence engine)",
  finance: "Personal finance (ledger, budgets, bills, savings)",
  time_tracking: "Time tracking (timer and manual entries)",
  projects: "Projects, subtasks and task dependencies",
  review: "Weekly and monthly review",
};

const PLANNED = ["Knowledge", "Growth", "Local worker"];

const SHIPPED_NOTES = [
  "## Plan executor (shipped)",
  "",
  "Approving a plan runs its read/prepare steps in order through `ToolRegistry.execute`. A",
  "commit (execute/destructive) step creates a normal durable approval and pauses the plan;",
  "approving it runs the tool once and the plan continues. Step results and statuses are",
  "persisted. Owners reconnect Google once to grant the new Docs/Sheets scopes.",
  "",
  "## Life modules (shipped; see ADR 0034)",
  "",
  "Notes and diary, files and images (stored in the database, 5 MB per file, 200 MB per owner),",
  "learning with spaced review, reading plans and logs, profile bio, birthday and photo, password",
  "change, notification preferences, and the `life` object on `GET /api/today`. Eight agent tools",
  "(read or prepare only). Daily learning, reading and diary nudges run as routines through the",
  "scheduler's quiet hours, pause and daily cap. Export and workspace wipe include all of it.",
  "",
  "## Days, Drive and Calendar sync (shipped; see ADR 0035)",
  "",
  "Every task belongs to a day and can carry a target and an outcome (achieved, partly, missed,",
  "skipped) with a daily score and streak. Notes, diary, daily summaries, files, vocabulary and the",
  "reading log back up to an organized `Compass/` folder in Google Drive (scope `drive.file`, never",
  "deletes). Timed tasks sync to Google Calendar. Both syncs ask for one approval per batch unless",
  "the owner sets the tool to Allow in Settings, Permissions. Tested only against simulated Google",
  "responses; owners reconnect Google once to grant the new Drive scope.",
  "",
  "## Habits, finance, time and review (shipped; see ADR 0036)",
  "",
  "One recurrence engine drives habits, recurring tasks, bills and income. Finance keeps a ledger of",
  "real transactions apart from expected ones; money writes by the agent use the `financial` access",
  "kind, which always asks and is never auto-approved. Sessions are server-side and revocable.",
  "Not yet covered: live-model agent quality for the new tools and Playwright journeys.",
];

export function parseCapabilities(source) {
  const match = source.match(
    /export const capabilities[^=]*=\s*\{([\s\S]*?)\n\}\s*;/,
  );
  if (!match) throw new Error("Could not find `capabilities` object literal.");
  const result = {};
  for (const m of match[1].matchAll(/(\w+)\s*:\s*"(api|mock)"/g)) {
    result[m[1]] = m[2];
  }
  if (Object.keys(result).length === 0) {
    throw new Error("No capability entries parsed from capabilities.ts.");
  }
  return result;
}

export function render(caps) {
  const rows = Object.entries(caps).map(([key, mode]) => {
    const label = LABELS[key] ?? key;
    const status = mode === "api" ? "Available" : "Mock / not available";
    return `| ${label} | \`${key}\` | \`${mode}\` | ${status} |`;
  });
  return [
    "# Feature status",
    "",
    "<!-- Generated by scripts/check-feature-status.mjs from frontend/lib/capabilities.ts. Do not edit by hand. -->",
    "",
    "Run `node scripts/check-feature-status.mjs --write` after changing capabilities.",
    "CI fails if a `mock` capability is advertised as Available.",
    "",
    "| Feature | Capability key | Mode | Status |",
    "| --- | --- | --- | --- |",
    ...rows,
    "",
    "`api` means the UI is backed by the live backend. `mock` means simulated data and",
    "must not be presented as a working feature.",
    "",
    "## Planned (not implemented)",
    "",
    ...PLANNED.map((p) => `- ${p}`),
    "",
    ...SHIPPED_NOTES,
    "",
  ].join("\n");
}

function main() {
  const caps = parseCapabilities(readFileSync(capabilitiesPath, "utf8"));
  const expected = render(caps);

  if (process.argv.includes("--write")) {
    writeFileSync(statusPath, expected);
    console.log(`Wrote ${statusPath}`);
    return;
  }

  if (!existsSync(statusPath)) {
    console.error(
      "docs/feature-status.md is missing. Run: node scripts/check-feature-status.mjs --write",
    );
    process.exit(1);
  }
  const actual = readFileSync(statusPath, "utf8");
  const errors = [];

  for (const [key, mode] of Object.entries(caps)) {
    if (mode !== "mock") continue;
    const row = actual
      .split("\n")
      .find((line) => line.includes(`\`${key}\``) && line.startsWith("|"));
    if (row && /\bAvailable\b/.test(row)) {
      errors.push(`Mock feature \`${key}\` is advertised as Available: ${row}`);
    }
  }
  if (actual !== expected) {
    errors.push(
      "docs/feature-status.md is out of date with frontend/lib/capabilities.ts. Run: node scripts/check-feature-status.mjs --write",
    );
  }

  if (errors.length > 0) {
    for (const e of errors) console.error(`feature-status: ${e}`);
    process.exit(1);
  }
  console.log("feature-status: OK");
}

main();
